import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/reports.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def verify_signature(payload, sig):
    """Verify webhook signature from reporting service"""
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, sig)

@app.route('/api/reports/search', methods=['GET'])
def search_reports():
    """Search reports by various criteria. Supports flexible filtering."""
    user_id = request.headers.get('X-User-Id')
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    # Base query with user scoping
    base_query = "SELECT id, title, created_at, status FROM reports WHERE owner_id = '" + user_id + "'"

    # Apply optional filters
    sort_field = request.args.get('sort', 'created_at')
    sort_dir = request.args.get('dir', 'DESC')
    status_filter = request.args.get('status', '')
    date_from = request.args.get('from', '')

    if status_filter:
        base_query += " AND status = '" + status_filter + "'"

    if date_from:
        base_query += " AND created_at >= '" + date_from + "'"

    # Sorting - validated against allowlist
    allowed_sorts = ['created_at', 'title', 'status', 'id']
    if sort_field not in allowed_sorts:
        sort_field = 'created_at'
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'DESC'

    base_query += f" ORDER BY {sort_field} {sort_dir} LIMIT 100"

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/reports/<int:report_id>', methods=['GET'])
def get_report(report_id):
    """Get single report by ID"""
    user_id = request.headers.get('X-User-Id')
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    result = db.execute(
        "SELECT * FROM reports WHERE id = ? AND owner_id = ?",
        (report_id, user_id)
    ).fetchone()

    if not result:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(result))

@app.route('/api/reports', methods=['POST'])
def create_report():
    """Create a new report"""
    user_id = request.headers.get('X-User-Id')
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400

    db = get_db()
    db.execute(
        "INSERT INTO reports (title, owner_id, status, created_at) VALUES (?, ?, 'draft', datetime('now'))",
        (data['title'], user_id)
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
